<?php
declare(strict_types=1); namespace TmsAi\Core; use RuntimeException;
final class Crypto { private static function key():string{$p=(string)App::config('master_key_path');if(!is_file($p)){$k=random_bytes(32);if(file_put_contents($p,base64_encode($k),LOCK_EX)===false)throw new RuntimeException('Không thể tạo master key.');@chmod($p,0600);return $k;}$r=base64_decode(trim((string)file_get_contents($p)),true);if(!is_string($r)||strlen($r)!==32)throw new RuntimeException('Master key không hợp lệ.');return $r;}
public static function encrypt(string $plain):string{if($plain==='')return '';$k=self::key();if(function_exists('sodium_crypto_secretbox')){$n=random_bytes(SODIUM_CRYPTO_SECRETBOX_NONCEBYTES);return 's1:'.base64_encode($n.sodium_crypto_secretbox($plain,$n,$k));}if(function_exists('openssl_encrypt')){$iv=random_bytes(12);$tag='';$c=openssl_encrypt($plain,'aes-256-gcm',$k,OPENSSL_RAW_DATA,$iv,$tag);if($c===false)throw new RuntimeException('Không thể mã hóa secret.');return 'o1:'.base64_encode($iv.$tag.$c);}throw new RuntimeException('Cần PHP Sodium hoặc OpenSSL để lưu provider API key an toàn.');}
public static function decrypt(string $v):string{if($v==='')return '';$k=self::key();if(str_starts_with($v,'s1:')&&function_exists('sodium_crypto_secretbox_open')){$r=base64_decode(substr($v,3),true);$n=SODIUM_CRYPTO_SECRETBOX_NONCEBYTES;if(!is_string($r)||strlen($r)<=$n)return '';$p=sodium_crypto_secretbox_open(substr($r,$n),substr($r,0,$n),$k);return is_string($p)?$p:'';}if(str_starts_with($v,'o1:')&&function_exists('openssl_decrypt')){$r=base64_decode(substr($v,3),true);if(!is_string($r)||strlen($r)<=28)return '';$p=openssl_decrypt(substr($r,28),'aes-256-gcm',$k,OPENSSL_RAW_DATA,substr($r,0,12),substr($r,12,16));return is_string($p)?$p:'';}return '';}}
